from lib import *
S=tokens(); at,vt=S['at'],S['vt']; pa,pb=S['pa'],S['pb']
def stock(p): return req('GET',f'/rest/v1/productos?select=stock&id=eq.{p}',at)[1][0]['stock']
c,cid=req('POST','/rest/v1/rpc/registrar_compra',at,{'p_proveedor_id':S['prov'],'p_numero_documento':'QA-001','p_forma_pago':'credito','p_vence_el':'2026-11-12','p_items':[{'producto_id':pa,'cantidad':10,'costo_unitario':1000},{'producto_id':pb,'cantidad':5,'costo_unitario':500}]})
sa,sb=stock(pa),stock(pb)
rec('PRO-003', c==200 and sa==10 and sb==5, f'Compra {cid} a crédito; stock A 0→{sa}, B 0→{sb} (una sola vez)', 'rpc registrar_compra')
S['compra']=cid; save(S)
c,h=req('GET',f'/rest/v1/compras?select=id,fecha,total,numero_documento&proveedor_id=eq.{S["prov"]}',at)
rec('PRO-004', len(h)==1 and int(h[0]['total'])==12500, f'Historial: {h}', 'Ficha del proveedor > Compras')
c,pp=req('GET',f'/rest/v1/productos?select=codigo&proveedor_id=eq.{S["prov"]}',at)
rec('PRO-002', len(pp)==2, f'Productos asociados: {[x["codigo"] for x in pp]}', 'productos.proveedor_id')
c,s0=req('GET',f'/rest/v1/compras_saldo?select=saldo,vence_el&id=eq.{cid}',at)
c1,p1=req('POST','/rest/v1/rpc/registrar_pago_proveedor',at,{'p_compra_id':cid,'p_monto':5000})
c,s1=req('GET',f'/rest/v1/compras_saldo?select=saldo&id=eq.{cid}',at)
c2,p2=req('POST','/rest/v1/rpc/registrar_pago_proveedor',at,{'p_compra_id':cid,'p_monto':999999})
c3,p3=req('POST','/rest/v1/rpc/registrar_pago_proveedor',at,{'p_compra_id':cid,'p_monto':7500})
c,s2=req('GET',f'/rest/v1/compras_saldo?select=saldo&id=eq.{cid}',at)
rec('PRO-005', s0[0]['saldo']==12500 and s1[0]['saldo']==7500 and c2>=400 and s2[0]['saldo']==0, f'Saldo 12.500 (vence {s0[0]["vence_el"]}) → abono 5.000 → 7.500; abono excesivo rechazado «{p2}»; pago final → 0', 'compras_saldo + registrar_pago_proveedor')
c,m=req('POST','/rest/v1/rpc/ajustar_inventario',at,{'p_producto_id':pa,'p_cantidad':2,'p_tipo':'ajuste_entrada','p_motivo':'QA ingreso de mercancía'})
s=stock(pa); rec('INV-010', c==200 and s==12, f'Ingreso +2 → stock 10→{s}; movimiento {m}', 'Cargar unidades > Otro origen')
c,m=req('POST','/rest/v1/rpc/ajustar_inventario',at,{'p_producto_id':pa,'p_cantidad':1,'p_tipo':'ajuste_salida','p_motivo':'QA salida'})
s=stock(pa); rec('INV-011', c==200 and s==11, f'Salida -1 → stock 12→{s}; movimiento {m}', 'ajustar_inventario ajuste_salida')
c,e=req('POST','/rest/v1/rpc/ajustar_inventario',at,{'p_producto_id':pa,'p_cantidad':500,'p_tipo':'ajuste_salida','p_motivo':'QA'})
rec('INV-012', c>=400 and stock(pa)==11, f'Salida de 500 → HTTP {c} «{e}»; stock sigue en 11', 'trigger aplicar_movimiento_inventario')
def bajo(): return any(x['id']==pb for x in req('GET','/rest/v1/stock_bajo?select=id',at)[1])
r=[('5 (> mín 3)',bajo())]
req('POST','/rest/v1/rpc/ajustar_inventario',at,{'p_producto_id':pb,'p_cantidad':2,'p_tipo':'ajuste_salida','p_motivo':'QA mínimo'}); r.append(('3 (= mín)',bajo()))
req('POST','/rest/v1/rpc/ajustar_inventario',at,{'p_producto_id':pb,'p_cantidad':1,'p_tipo':'ajuste_salida','p_motivo':'QA mínimo'}); r.append(('2 (< mín)',bajo()))
req('POST','/rest/v1/rpc/ajustar_inventario',at,{'p_producto_id':pb,'p_cantidad':3,'p_tipo':'ajuste_entrada','p_motivo':'QA mínimo'}); r.append(('5 (> mín)',bajo()))
rec('INV-014', [x[1] for x in r]==[False,True,True,False], 'Alerta: '+', '.join(f'stock {a} → {"alerta" if b else "sin alerta"}' for a,b in r), 'vista stock_bajo (stock <= stock_min)')
c,mv=req('GET',f'/rest/v1/movimientos_inventario?select=tipo,cantidad,stock_despues,motivo&producto_id=eq.{pa}&order=id',at)
c2,x=req('PATCH',f'/rest/v1/movimientos_inventario?producto_id=eq.{pa}',at,{'cantidad':99})
S['mov_hist']=len(mv); save(S)
print(mv, c2, x)
